          "claim": "ts-travel-service client POST to basic fails with 500, and its trips/left server span returns 500."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_status_code='Error' AND attr_span_kind IN ('Client','Server') GROUP BY ALL",
          "claim": "ts-travel2-service client POST to basic fails with 500, and its trip_detail server span returns 500."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_status_code='Error' AND attr_span_kind IN ('Client','Server') GROUP BY ALL",
          "claim": "ts-route-plan-service client POST calls return 500 with BasicErrorController children from basic; its routePlan server spans return 500."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
